int main()
{
    std::vector<int> first{ 1, 2, 3 };
    std::vector<int> second{ 10, -4 };
    std::vector<int> none{};

    long long total{ 100 };
    addAll(first, total);
    std::cout << "after-first " << total << "\n";
    addAll(second, total);
    std::cout << "after-second " << total << "\n";
    addAll(none, total);
    std::cout << "after-empty " << total << "\n";

    long long negative{ -5 };
    addAll(first, negative);
    std::cout << "negative " << negative << "\n";

    std::vector<int> many(10000, 1000000);
    long long wide{ 0 };
    addAll(many, wide);
    std::cout << "wide " << wide << "\n";

    return 0;
}

