#include <iostream>
#include <vector>

void addAll(const std::vector<int>& values, long long& total)
{
    for (int value : values)
    {
        total += value;
    }
}

int main()
{
    std::vector<int> evens{};
    std::vector<int> odds{};
    int x{};
    int position{};

    while (std::cin >> x)
    {
        if (position % 2 == 0) evens.push_back(x);
        else odds.push_back(x);
        ++position;
    }

    long long evenTotal{};
    addAll(evens, evenTotal);

    long long oddTotal{};
    addAll(odds, oddTotal);

    long long total{};
    addAll(evens, total);
    addAll(odds, total);

    std::cout << "even-positions " << evenTotal << "\n";
    std::cout << "odd-positions " << oddTotal << "\n";
    std::cout << "total " << total << "\n";

    return 0;
}
